from z3 import *

def mins(h, m):
    return h * 60 + m

DURATION = 30
WORK_START = mins(9, 0)
WORK_END = mins(17, 0)
DAY_NAMES = ["Monday", "Tuesday"]

day = Int("day")
start = Int("start")

opt = Optimize()

opt.add(day >= 0, day < len(DAY_NAMES))
opt.add(start >= WORK_START, start + DURATION <= WORK_END)

busy = {
    0: {
        "Shirley": [
            (mins(10, 30), mins(11, 0)),
            (mins(12, 0), mins(12, 30)),
            (mins(16, 0), mins(16, 30)),
        ],
        "Albert": [
            (mins(9, 0), mins(17, 0)),
        ],
    },
    1: {
        "Shirley": [
            (mins(9, 30), mins(10, 0)),
        ],
        "Albert": [
            (mins(9, 30), mins(11, 0)),
            (mins(11, 30), mins(12, 30)),
            (mins(13, 0), mins(16, 0)),
            (mins(16, 30), mins(17, 0)),
        ],
    },
}

for d in range(len(DAY_NAMES)):
    for intervals in busy[d].values():
        for b_start, b_end in intervals:
            opt.add(Implies(day == d, Or(start + DURATION <= b_start, start >= b_end)))

preference_penalty = If(And(day == 1, start > mins(10, 30)), 1, 0)

opt.minimize(preference_penalty)
opt.minimize(day)
opt.minimize(start)

if opt.check() == sat:
    model = opt.model()
    d = model.eval(day, model_completion=True).as_long()
    st = model.eval(start, model_completion=True).as_long()
    et = st + DURATION

    def fmt(t):
        return f"{t // 60:02d}:{t % 60:02d}"

    print([DAY_NAMES[d], fmt(st), fmt(et)])
else:
    print("[]")

from z3 import *

def to_minutes(t):
    h, m = t.split(":")
    return int(h) * 60 + int(m)

def fmt(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"

days = ["Monday", "Tuesday", "Wednesday", "Thursday"]
DURATION = 60
WORK_START = to_minutes("09:00")
WORK_END = to_minutes("17:00")

schedules = {
    "Natalie": {
        0: [("09:00", "09:30"), ("10:00", "12:00"), ("12:30", "13:00"), ("14:00", "14:30"), ("15:00", "16:30")],
        1: [("09:00", "09:30"), ("10:00", "10:30"), ("12:30", "14:00"), ("16:00", "17:00")],
        2: [("11:00", "11:30"), ("16:00", "16:30")],
        3: [("10:00", "11:00"), ("11:30", "15:00"), ("15:30", "16:00"), ("16:30", "17:00")],
    },
    "William": {
        0: [("09:30", "11:00"), ("11:30", "17:00")],
        1: [("09:00", "13:00"), ("13:30", "16:00")],
        2: [("09:00", "12:30"), ("13:00", "14:30"), ("15:30", "16:00"), ("16:30", "17:00")],
        3: [("09:00", "10:30"), ("11:00", "11:30"), ("12:00", "12:30"), ("13:00", "14:00"), ("15:00", "17:00")],
    },
}

day = Int("day")
start = Int("start")

solver = Optimize()
solver.add(day >= 0)
solver.add(day < len(days))
solver.add(start >= WORK_START)
solver.add(start + DURATION <= WORK_END)

for schedule in schedules.values():
    for d, intervals in schedule.items():
        for busy_start, busy_end in intervals:
            bs = to_minutes(busy_start)
            be = to_minutes(busy_end)
            solver.add(Or(day != d, start + DURATION <= bs, be <= start))

solver.minimize(day * 1440 + start)

if solver.check() == sat:
    model = solver.model()
    d = model.eval(day).as_long()
    st = model.eval(start).as_long()
    en = st + DURATION
    print([days[d], fmt(st), fmt(en)])
else:
    raise SystemExit
